by-hand.fence:
[[artifacts.build]] id = "build-hello" mechanism = "build:cargo" outputs = [{ id = "hello", kind = "executable", select = { package = "hello", bin = "hello" } }] config = { offline = true }
[[deploy.target]] id = "local" artifact = "hello" mechanism = "deploy:vibe-bin" config = { command = "hello" }
[deploy] default_profile = "local"
[deploy.profiles.local] targets = ["local"]
